      return { ...single, tipo_tar: 'simple', componentes: [], componentes_detectados: components.map((c) => c.original), componentes_no_encontrados: [components[0].original], componentes_canonicos: canonicalizeCombination(components[0].normalizado), code: single.code === 'sin_coste_vigente' ? 'sin_coste_vigente' : 'componente_no_encontrado', reason: single.reason || 'componente_no_encontrado' };
