    if (missing.length || noCurrent.length) return { found: false, code: noCurrent.length ? 'sin_coste_vigente_para_componente' : 'componente_no_encontrado', reason: noCurrent.length ? 'sin_coste_vigente_para_componente' : 'componente_no_encontrado', search: extractedFromParentheses ? 'componentes_parentesis' : 'componentes TAR compuesto', ...detail };
